document.addEventListener("DOMContentLoaded",function(){document.querySelectorAll(".complete-offer").forEach(e=>{e.addEventListener("click",function(){const t=this.dataset.offerId,o=this.dataset.offerUrl;window.open(o,"_blank");const n=new FormData;n.append("action","completeOffer"),n.append("offer_id",t),fetch("../controllers/OfferwallController.php",{method:"POST",body:n}).then(e=>e.json()).then(e=>{e.success?Toastify({text:e.message,duration:3e3,className:"info",style:{background:"linear-gradient(to right, #00b09b, #96c93d)"}}).showToast():Toastify({text:e.message||"An unknown error occurred.",duration:3e3,className:"error",style:{background:"linear-gradient(to right, #ff5f6d, #ffc371)"}}).showToast()}).catch(e=>{console.error("Error:",e),Toastify({text:"A network error occurred.",duration:3e3,className:"error",style:{background:"linear-gradient(to right, #ff5f6d, #ffc371)"}}).showToast()})})})});
